import subprocess, sys, concurrent.futures, io, csv, os
from PIL import Image

def fetch_mean(args):
    kind, ident, url = args
    try:
        r = subprocess.run(["curl","-s","--max-time","25","-o","/tmp/f.jpg","-w","%{http_code}",url],capture_output=True,text=True)
        code = r.stdout.strip()
        if code != "200": return (kind, ident, None)
        im = Image.open("/tmp/f.jpg").convert("RGB")
        im2 = im.resize((1,1), Image.BOX)
        return (kind, ident, im2.getpixel((0,0)))
    except Exception as e:
        return (kind, ident, None)

if __name__ == "__main__":
    kind = sys.argv[1]; outfile = sys.argv[2]
    # lines: id<TAB>url
    jobs=[]
    for line in open(sys.argv[3]):
        line=line.strip()
        if not line: continue
        ident,url = line.split("\t")
        jobs.append((kind,ident,url))
    print("jobs:",len(jobs))
    results={}
    with concurrent.futures.ThreadPoolExecutor(max_workers=16) as ex:
        for i,(k,ident,c) in enumerate(ex.map(fetch_mean, jobs)):
            results[ident]=c
            if i%250==0: print("progress",i,flush=True)
    miss=sum(1 for v in results.values() if v is None)
    with open(outfile,"w",newline="") as f:
        w=csv.writer(f)
        for ident,c in sorted(results.items(), key=lambda kv:int(kv[0])):
            w.writerow([ident] + (list(c) if c else ["NA"]))
    print("done. missing:",miss)
